// Generated by perch. Regenerating overwrites this file.
//
// The fixed half of the generated app: a JSON value, the three watch pollers,
// the action verbs, and the AppKit drawing of what Render.swift decides.
// Nothing here depends on menubar.yaml.

import AppKit
import Foundation

// MARK: - MenuIcon

/// What the status item shows. A symbol is drawn as a template, so macOS tints
/// it for the menu bar's own appearance and for whether the bar is selected. An
/// asset is artwork the consuming repo drew, which macOS will not tint and
/// which therefore has to carry its own color.
enum MenuIcon {
    case symbol(String)
    case asset(String)

    func image() -> NSImage? {
        switch self {
        case .symbol(let name):
            let image = NSImage(systemSymbolName: name, accessibilityDescription: nil)
            image?.isTemplate = true
            return image
        case .asset(let name):
            guard let image = MenuIcon.load(name), image.size.height > 0 else { return nil }
            // Measured off the bar rather than fixed at the 18pt a menu bar used
            // to be: the bar has been taller than that for several releases, and
            // artwork sized to the old number sits in the middle of its frame
            // looking like a mistake. The inset is what keeps it off the edges.
            let height = max(NSStatusBar.system.thickness - 5, 12)
            image.size = NSSize(width: height * (image.size.width / image.size.height), height: height)
            return image
        }
    }

    /// How faint to draw, approximating the fade macOS gives a template when the
    /// menu bar goes inactive and gives artwork not at all. The bar is taken as
    /// inactive when the item's own screen is not the one holding the active
    /// menu bar, which is right for the two common cases — another display has
    /// focus, or a full screen app owns this one — and wrong for anything else
    /// that dims the bar. A template is left alone: it has already faded, and
    /// fading it twice is worse than not matching.
    func alpha(on button: NSStatusBarButton) -> CGFloat {
        guard case .asset = self else { return 1 }
        guard let screen = button.window?.screen, let active = NSScreen.main else { return 1 }
        return screen == active ? 1 : 0.55
    }

    /// `<name>~dark.png` where the bundle carries one. A template gets its two
    /// appearances from macOS; artwork that keeps its own color does not, so an
    /// asset whose outline must read against both menu bars ships both.
    private static func load(_ name: String) -> NSImage? {
        let dark = NSApp.effectiveAppearance.bestMatch(from: [.aqua, .darkAqua]) == .darkAqua
        if dark, let path = Bundle.main.path(forResource: name + "~dark", ofType: "png"),
           let image = NSImage(contentsOfFile: path) {
            return image
        }
        guard let path = Bundle.main.path(forResource: name, ofType: "png") else { return nil }
        return NSImage(contentsOfFile: path)
    }
}

// MARK: - JSONValue

/// The value an undeclared watch binds. A watch with a `shape:` decodes into a
/// generated struct instead and never touches this.
enum JSONValue: Equatable {
    case null
    case bool(Bool)
    case int(Int)
    case double(Double)
    case string(String)
    case array([JSONValue])
    case object([String: JSONValue])
}

extension JSONValue: Decodable {
    init(from decoder: Decoder) throws {
        if let c = try? decoder.singleValueContainer() {
            if c.decodeNil() {
                self = .null
                return
            }
            if let v = try? c.decode(Bool.self) {
                self = .bool(v)
                return
            }
            if let v = try? c.decode(Int.self) {
                self = .int(v)
                return
            }
            if let v = try? c.decode(Double.self) {
                self = .double(v)
                return
            }
            if let v = try? c.decode(String.self) {
                self = .string(v)
                return
            }
            if let v = try? c.decode([JSONValue].self) {
                self = .array(v)
                return
            }
            if let v = try? c.decode([String: JSONValue].self) {
                self = .object(v)
                return
            }
        }
        self = .null
    }

    static func parse(_ text: String) -> JSONValue {
        guard let data = text.data(using: .utf8) else { return .null }
        return (try? JSONDecoder().decode(JSONValue.self, from: data)) ?? .null
    }
}

extension JSONValue {
    init(_ v: Bool) { self = .bool(v) }
    init(_ v: Int) { self = .int(v) }
    init(_ v: Double) { self = .double(v) }
    init(_ v: String) { self = .string(v) }

    subscript(key: String) -> JSONValue {
        if case .object(let o) = self { return o[key] ?? .null }
        return .null
    }

    subscript(index: Int) -> JSONValue {
        if case .array(let a) = self, a.indices.contains(index) { return a[index] }
        return .null
    }

    var exists: Bool { self != .null }

    var asBool: Bool {
        switch self {
        case .bool(let b): return b
        case .int(let i): return i != 0
        case .double(let d): return d != 0
        case .string(let s): return !s.isEmpty
        case .array(let a): return !a.isEmpty
        case .object(let o): return !o.isEmpty
        case .null: return false
        }
    }

    var asInt: Int {
        switch self {
        case .int(let i): return i
        // Int(Double) traps outside Int's range, and the double came from
        // whatever the watch printed.
        case .double(let d): return Int(exactly: d.rounded()) ?? 0
        case .bool(let b): return b ? 1 : 0
        case .string(let s): return Int(s) ?? 0
        default: return 0
        }
    }

    var asDouble: Double {
        switch self {
        case .double(let d): return d
        case .int(let i): return Double(i)
        case .bool(let b): return b ? 1 : 0
        case .string(let s): return Double(s) ?? 0
        default: return 0
        }
    }

    var asString: String {
        switch self {
        case .string(let s): return s
        case .int(let i): return String(i)
        case .double(let d):
            if d == d.rounded(), let i = Int(exactly: d) { return String(i) }
            return String(d)
        case .bool(let b): return String(b)
        case .null: return ""
        case .array, .object: return ""
        }
    }

    var asArray: [JSONValue] {
        if case .array(let a) = self { return a }
        return []
    }

    var size: Int {
        switch self {
        case .array(let a): return a.count
        case .object(let o): return o.count
        case .string(let s): return s.count
        default: return 0
        }
    }

    func contains(_ needle: JSONValue) -> Bool { asArray.contains(needle) }
}

// MARK: - Boxes

/// A value one thread fills in and another reads. Used where a completion
/// handler outlives the call that started it.
private final class Box<T> {
    private var value: T
    private let lock = NSLock()

    init(_ initial: T) { value = initial }

    func mutate(_ body: (inout T) -> Void) {
        lock.lock()
        defer { lock.unlock() }
        body(&value)
    }

    var current: T {
        lock.lock()
        defer { lock.unlock() }
        return value
    }
}

// MARK: - Watches

struct RunOutcome {
    var ok = false
    var code = -1
    var out = ""
    var err = ""
}

struct HTTPOutcome {
    var ok = false
    var status = 0
    var out = ""
}

struct LaunchAgentOutcome {
    var installed = false
    var loaded = false
    var running = false
    var pid = 0
    var label = ""
    var plist = "" // expanded
}

/// Where a user's own LaunchAgents live, and how launchctl is told about them.
enum Launchd {
    /// Read at runtime because it is the one part of addressing an agent that
    /// differs between Macs: 501 is only the first account a Mac creates.
    static var domain: String { "gui/\(getuid())" }

    static func target(_ label: String) -> String { domain + "/" + label }

    /// launchctl is handed argv directly, with no shell to expand a tilde.
    static func expand(_ path: String) -> String { (path as NSString).expandingTildeInPath }
}

enum Watcher {
    /// Runs argv directly — never a shell. /usr/bin/env performs the PATH
    /// lookup, which a LaunchAgent's minimal environment would otherwise miss.
    static func run(_ argv: [String]) -> RunOutcome {
        guard !argv.isEmpty else { return RunOutcome() }
        let task = Process()
        task.executableURL = URL(fileURLWithPath: "/usr/bin/env")
        task.arguments = argv
        let outPipe = Pipe()
        let errPipe = Pipe()
        task.standardOutput = outPipe
        task.standardError = errPipe
        do {
            try task.run()
        } catch {
            return RunOutcome(ok: false, code: -1, out: "", err: "\(error)")
        }
        // Both pipes drain at once. Reading one to EOF and then the other
        // deadlocks a child that fills the second pipe's buffer meanwhile.
        let stderrBox = Box(Data())
        let draining = DispatchQueue(label: "perch.run.stderr")
        draining.async {
            stderrBox.mutate { $0 = errPipe.fileHandleForReading.readDataToEndOfFile() }
        }
        let outData = outPipe.fileHandleForReading.readDataToEndOfFile()
        draining.sync {}
        let errData = stderrBox.current
        task.waitUntilExit()
        let code = Int(task.terminationStatus)
        return RunOutcome(
            ok: code == 0,
            code: code,
            out: String(data: outData, encoding: .utf8) ?? "",
            err: String(data: errData, encoding: .utf8) ?? ""
        )
    }

    static func http(_ urlString: String) -> HTTPOutcome {
        guard let url = URL(string: urlString) else { return HTTPOutcome() }
        // Boxed because the wait below can time out while the request is still
        // in flight, leaving the handler to write after this call has returned.
        let box = Box(HTTPOutcome())
        let done = DispatchSemaphore(value: 0)
        var request = URLRequest(url: url)
        request.timeoutInterval = 5
        URLSession.shared.dataTask(with: request) { data, response, _ in
            box.mutate { outcome in
                if let http = response as? HTTPURLResponse {
                    outcome.status = http.statusCode
                    outcome.ok = (200..<300).contains(http.statusCode)
                }
                if let data { outcome.out = String(data: data, encoding: .utf8) ?? "" }
            }
            done.signal()
        }.resume()
        _ = done.wait(timeout: .now() + 10)
        return box.current
    }

    static func exists(_ path: String) -> Bool {
        FileManager.default.fileExists(atPath: (path as NSString).expandingTildeInPath)
    }

    /// `launchctl print` exiting 0 says launchd knows the label, which is not
    /// the same as the job having a process: one that has run and exited is
    /// still loaded. The top-level `state =` line is what separates the two,
    /// and it is exactly one tab in — deeper ones describe the job's endpoints
    /// and are active whether or not the job itself is.
    static func launchAgent(label: String, plist: String) -> LaunchAgentOutcome {
        var o = LaunchAgentOutcome(label: label, plist: Launchd.expand(plist))
        o.installed = FileManager.default.fileExists(atPath: o.plist)
        let printed = run(["launchctl", "print", Launchd.target(label)])
        o.loaded = printed.ok
        guard printed.ok else { return o }
        for line in printed.out.split(separator: "\n", omittingEmptySubsequences: false) {
            guard line.hasPrefix("\t"), !line.hasPrefix("\t\t") else { continue }
            let field = line.dropFirst()
            if field.hasPrefix("state = ") { o.running = field.dropFirst(8) == "running" }
            if field.hasPrefix("pid = ") { o.pid = Int(field.dropFirst(6)) ?? 0 }
        }
        return o
    }
}

// MARK: - Actions

enum Act {
    /// Every action re-polls on completion, so acting on the menu visibly
    /// changes it. A non-zero exit raises an alert naming the command.
    static func run(_ argv: [String], then repoll: @escaping () -> Void) {
        DispatchQueue.global(qos: .userInitiated).async {
            let outcome = Watcher.run(argv)
            DispatchQueue.main.async {
                if !outcome.ok { alert(argv.joined(separator: " "), outcome.err) }
                repoll()
            }
        }
    }

    static func open(_ target: String) {
        if let url = URL(string: target), url.scheme != nil {
            NSWorkspace.shared.open(url)
        } else {
            NSWorkspace.shared.open(URL(fileURLWithPath: (target as NSString).expandingTildeInPath))
        }
    }

    static func post(_ urlString: String, body: String, then repoll: @escaping () -> Void) {
        guard let url = URL(string: urlString) else {
            alert("POST \(urlString)", "Not a URL.")
            return
        }
        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        request.httpBody = body.data(using: .utf8)
        URLSession.shared.dataTask(with: request) { _, response, error in
            DispatchQueue.main.async {
                let status = (response as? HTTPURLResponse)?.statusCode ?? 0
                if error != nil || !(200..<300).contains(status) {
                    alert("POST \(urlString)", error?.localizedDescription ?? "HTTP \(status)")
                }
                repoll()
            }
        }.resume()
    }

    /// The three things perch will do to a LaunchAgent. The verbs are the
    /// modern ones: `load`/`unload` also write launchd's disabled database,
    /// which is a second effect nobody asking for Start is asking for.
    static func agent(label: String, plist: String, verb: LaunchAgentVerb, then repoll: @escaping () -> Void) {
        DispatchQueue.global(qos: .userInitiated).async {
            let outcome: RunOutcome
            switch verb {
            case .start:
                outcome = Watcher.run(["launchctl", "bootstrap", Launchd.domain, Launchd.expand(plist)])
            case .stop:
                outcome = Watcher.run(["launchctl", "bootout", Launchd.target(label)])
            case .restart:
                outcome = restart(label: label, plist: plist)
            }
            DispatchQueue.main.async {
                if !outcome.ok { alert(verb.gerund + " " + label, outcome.err) }
                repoll()
            }
        }
    }

    /// bootout returns before launchd has let go of the label, and
    /// bootstrapping into that gap fails with Input/output error — so this
    /// polls until the label is genuinely gone rather than bootstrapping blind.
    private static func restart(label: String, plist: String) -> RunOutcome {
        _ = Watcher.run(["launchctl", "bootout", Launchd.target(label)])
        for _ in 0..<40 {
            if !Watcher.run(["launchctl", "print", Launchd.target(label)]).ok {
                return Watcher.run(["launchctl", "bootstrap", Launchd.domain, Launchd.expand(plist)])
            }
            Thread.sleep(forTimeInterval: 0.05)
        }
        return RunOutcome(
            ok: false, code: -1, out: "",
            err: "launchd still holds \(label) after two seconds, so it was not bootstrapped again."
        )
    }

    static func perform(_ action: MenuAction, then repoll: @escaping () -> Void) {
        switch action {
        case .run(let argv): run(argv, then: repoll)
        case .open(let target): open(target)
        case .post(let url, let body): post(url, body: body, then: repoll)
        case .agent(let label, let plist, let verb): agent(label: label, plist: plist, verb: verb, then: repoll)
        case .quit: NSApp.terminate(nil)
        }
    }

    static func alert(_ command: String, _ detail: String) {
        let a = NSAlert()
        a.messageText = "\(command) failed"
        a.informativeText = detail.isEmpty ? "No output." : detail
        a.alertStyle = .warning
        a.runModal()
    }
}

// MARK: - Menu

/// An NSMenuItem that carries its own closure, so the generated menu builder
/// does not need a selector per action.
final class ActionItem: NSMenuItem {
    private let handler: () -> Void

    init(title: String, handler: @escaping () -> Void) {
        self.handler = handler
        super.init(title: title, action: nil, keyEquivalent: "")
        self.target = self
        self.action = #selector(fire)
    }

    @available(*, unavailable)
    required init(coder: NSCoder) { fatalError("not supported") }

    @objc private func fire() { handler() }
}

// MARK: - Face and menu

/// What the status item shows, decided from one poll's results.
struct Face {
    var icon: MenuIcon
    var dim = false
    var badge = ""
}

/// What agent: does to a LaunchAgent. Closed, because each one is a launchctl
/// invocation perch writes rather than the author.
enum LaunchAgentVerb: String {
    case start, stop, restart

    var gerund: String {
        switch self {
        case .start: return "Starting"
        case .stop: return "Stopping"
        case .restart: return "Restarting"
        }
    }
}

/// What activating a menu item does. It is lowered when the menu is built, so
/// an item runs what it showed.
enum MenuAction {
    case run([String])
    case open(String)
    case post(url: String, body: String)
    case agent(label: String, plist: String, verb: LaunchAgentVerb)
    case quit
}

/// One menu entry before AppKit draws it. An item with no action is a label,
/// which macOS shows disabled.
enum MenuNode {
    case separator
    case item(String, MenuAction?)
    case submenu(String, [MenuNode])
}

/// Drops separators with nothing beside them: leading, trailing, and every one
/// after the first in a run. A divider earns its line by dividing two things,
/// and which items a poll leaves out is not knowable where they are written —
/// so guarding each separator by hand would mean repeating the conditions of
/// every item around it.
func tidy(_ nodes: [MenuNode]) -> [MenuNode] {
    var out: [MenuNode] = []
    for node in nodes {
        if case .separator = node {
            if out.isEmpty { continue }
            if case .separator = out[out.count - 1] { continue }
            out.append(node)
            continue
        }
        if case .submenu(let title, let items) = node {
            out.append(.submenu(title, tidy(items)))
            continue
        }
        out.append(node)
    }
    if let last = out.last, case .separator = last { out.removeLast() }
    return out
}

enum Draw {
    static func face(_ face: Face, on button: NSStatusBarButton) {
        button.image = face.icon.image()
        button.alphaValue = face.icon.alpha(on: button)
        button.appearsDisabled = face.dim
        button.title = face.badge.isEmpty ? "" : " " + face.badge
    }

    /// Replaces whatever the menu held: it is rebuilt from the last poll every
    /// time it opens.
    static func menu(_ nodes: [MenuNode], into menu: NSMenu, repoll: @escaping () -> Void) {
        menu.removeAllItems()
        for node in nodes {
            switch node {
            case .separator:
                menu.addItem(NSMenuItem.separator())
            case .item(let title, nil):
                menu.addItem(NSMenuItem(title: title, action: nil, keyEquivalent: ""))
            case .item(let title, let action?):
                menu.addItem(ActionItem(title: title) { Act.perform(action, then: repoll) })
            case .submenu(let title, let items):
                let item = NSMenuItem(title: title, action: nil, keyEquivalent: "")
                let sub = NSMenu()
                Draw.menu(items, into: sub, repoll: repoll)
                item.submenu = sub
                menu.addItem(item)
            }
        }
    }
}
